	AND (saga_instances.claimed_until IS NULL OR saga_instances.claimed_until <= sqlc.arg(lease_expired_by))
ORDER BY saga_instances.next_attempt, saga_instances.created_at, saga_instances.id
LIMIT COALESCE(sqlc.narg(result_limit), 50)
FOR UPDATE SKIP LOCKED;

