-- name: InsertSagaInstance :exec
INSERT INTO saga_instances (
	id,
	definition,
	status,
	current_step,
	step_names,
	state,
	attempts,
	last_error,
	resume_status,
	created_at,
	next_attempt
) VALUES (
	sqlc.arg(id),
	sqlc.arg(definition),
	sqlc.arg(status),
	sqlc.arg(current_step),
	sqlc.arg(step_names),
	sqlc.narg(state),
	sqlc.arg(attempts),
	sqlc.arg(last_error),
	sqlc.arg(resume_status),
	sqlc.arg(created_at),
	sqlc.arg(next_attempt)
);

-- name: ClaimSagaInstances :execrows
UPDATE saga_instances SET
	claimed_until = sqlc.arg(claimed_until),
	last_updated_at = sqlc.arg(last_updated_at),
	attempts = attempts + 1
WHERE saga_instances.status IN (sqlc.arg(running_status), sqlc.arg(compensating_status))
	AND saga_instances.id = ANY(sqlc.arg(ids)::text[]);

-- name: AdvanceSagaInstance :execrows
UPDATE saga_instances SET
	status = sqlc.arg(status),
	current_step = sqlc.arg(current_step),
	state = sqlc.narg(state),
	last_error = sqlc.arg(last_error),
	resume_status = sqlc.arg(resume_status),
	next_attempt = sqlc.arg(next_attempt),
	last_updated_at = sqlc.arg(last_updated_at),
	attempts = 0
WHERE saga_instances.id = sqlc.arg(id)
	AND saga_instances.status IN (sqlc.arg(running_status), sqlc.arg(compensating_status));

